src/components/features/dashboard/bookin:
'use client';

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { AlertCircle, RefreshCw, LayoutGrid, Users, CheckCircle2, Trash2, X, Info, MapPin } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { AssignmentToolbar } from '@/components/features/dashboard/manual-assignment/AssignmentToolbar';
import { ValidationChecks } from '@/components/features/dashboard/manual-assignment/ValidationChecks';
import { TableFloorPlan } from '@/components/features/dashboard/TableFloorPlan';
import { Alert, AlertDescription } from '@/components/ui/alert';
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { useBookingService } from '@/contexts/ops-services';
import { useAssignmentContext } from '@/hooks/ops/useAssignmentContext';
import { useToast } from '@/hooks/use-toast';
import { HttpError } from '@/lib/http/errors';
import { queryKeys } from '@/lib/query/keys';
import { generateIdempotencyKey } from '@/lib/utils/idempotency';

import type { ManualSelectionCheck, ManualValidationResult } from '@/services/ops/bookings';
import type { OpsTodayBooking, OpsTodayBookingsSummary } from '@/types/ops';

type BookingAssignmentTabContentProps = {
    booking: OpsTodayBooking;
    restaurantId: string;
    date: string;
    onUnassignTable?: (tableId: string) => Promise<unknown>;
    onAssignmentComplete?: () => void;
};

export function BookingAssignmentTabContent({ booking, restaurantId, date, onUnassignTable, onAssignmentComplete }: BookingAssignmentTabContentProps) {
    const { toast } = useToast();
    const bookingService = useBookingService();
    const queryClient = useQueryClient();

    // -- Local State --
    const [selectedTables, setSelectedTables] = useState<string[]>([]);
    const [validationResult, setValidationResult] = useState<ManualValidationResult | null>(null);
    const [onlyAvailable, setOnlyAvailable] = useState(true);
    const [unassignTableId, setUnassignTableId] = useState<string | null>(null);
    const [errorBanner, setErrorBanner] = useState<string | null>(null);

    // Track previous selection to detect changes
    const prevSelectedTablesRef = useRef<string[]>([]);

    // -- Context --
    const {
        data: assignmentContext,
        isLoading: assignmentContextLoading,
        error: assignmentContextError,
        refetch: refetchAssignmentContext,
    } = useAssignmentContext({
        bookingId: booking.id,
        enabled: true,
    });

    // -- Derived State --
    // Simplified logic for the new direct assignment context
    const validationChecks = useMemo(() => {
        // Validation is now primarily handled by the backend on assignment.
        // This can be used for simple client-side checks if needed in the future.
        return [] as ManualSelectionCheck[];
    }, []);

    // Prefer current selection; otherwise reflect existing assignments so capacity/seat summary is meaningful even after assignment.
    const effectiveSelectedIds = useMemo(
        () => (selectedTables.length > 0 ? selectedTables : assignmentContext?.bookingAssignments ?? []),
        [assignmentContext?.bookingAssignments, selectedTables]
    );

    const selectedCapacity = useMemo(() => {
        return effectiveSelectedIds.reduce((sum, tableId) => {
            const table = assignmentContext?.tables.find(t => t.id === tableId);
            return sum + (table?.capacity ?? 0);
        }, 0);
    }, [effectiveSelectedIds, assignmentContext]);

    const tableMap = useMemo(() => {
        if (!assignmentContext) return new Map();
        return new Map(assignmentContext.tables.map(t => [t.id, t]));
    }, [assignmentContext]);

    const assignedTables = useMemo(() => {
        if (!assignmentContext) return [];
        return assignmentContext.bookingAssignments
            .map(id => tableMap.get(id))
            .filter((t): t is NonNullable<typeof t> => !!t);
    }, [assignmentContext, tableMap]);

    // -- Mutations --
    // Direct table assignment (atomic operation) with standard optimistic update pattern.
    const directAssignMutation = useMutation<
        Awaited<ReturnType<typeof bookingService.assignTablesDirect>>,
        unknown,
        string[],
        { summaryKey: ReturnType<(typeof queryKeys)['opsDashboard']['summary']>; previousSummary?: OpsTodayBookingsSummary }
    >({
        mutationFn: async (tableIds) => {
            return await bookingService.assignTablesDirect({
                bookingId: booking.id,
                tableIds,
                idempotencyKey: generateIdempotencyKey(),
                requireAdjacency: false,
            });
        },
        onMutate: async (tableIds) => {
            setErrorBanner(null);

            const summaryKey = queryKeys.opsDashboard.summary(restaurantId, date);

            // Step 1: cancel any in-flight refetches for the same summary
            await queryClient.cancelQueries({ queryKey: summaryKey });

            // Step 2: snapshot previous state
            const previousSummary = queryClient.getQueryData<OpsTodayBookingsSummary>(summaryKey);

            // Step 3: optimistically update cache (dashboard list cards)
            queryClient.setQueryData<OpsTodayBookingsSummary>(summaryKey, (current) => {
                if (!current) return current;

                const members: OpsTodayBooking['tableAssignments'][number]['members'] = tableIds.map((tableId) => {
                    const t = tableMap.get(tableId);
                    return {
                        tableId,
                        tableNumber: t?.tableNumber ?? '?',
                        capacity: t?.capacity ?? null,
                        section: t?.section ?? null,
                    };
                });

                const capacitySum = members.reduce((sum, member) => sum + (member.capacity ?? 0), 0);
                const optimisticAssignments: OpsTodayBooking['tableAssignments'] =
                    members.length > 0
                        ? [
                            {
                                groupId: null,
                                capacitySum,
                                members,
                            },
                        ]
                        : [];

                return {
                    ...current,
                    bookings: current.bookings.map((b) => {
                        if (b.id !== booking.id) return b;
                        return {
                            ...b,
                            tableAssignments: optimisticAssignments,
                            requiresTableAssignment: optimisticAssignments.length === 0 && b.status !== 'cancelled' && b.status !== 'no_show',
                        };
                    }),
                };
            });

            // Step 4: return context for rollback
            return { summaryKey, previousSummary };
        },
        onError: (error: unknown, _tableIds, context) => {
            if (context?.previousSummary) {
                queryClient.setQueryData(context.summaryKey, context.previousSummary);
            }

            console.error('[BookingAssignmentTabContent] Assignment failed:', error);

            // Handle HttpError with validation details
            if (error instanceof HttpError) {
                const details = error.details as { checks?: Array<{ id: string; passed: boolean; message: string }> } | undefined;
                if (details?.checks && details.checks.length > 0) {
                    const failedChecks = details.checks.filter((c) => !c.passed);
                    setValidationResult({
                        ok: failedChecks.length === 0,
                        checks: failedChecks.map((c) => ({ id: c.id as ManualSelectionCheck['id'], status: 'error', message: c.message })),
                        summary: {
                            tableCount: selectedTables.length,
                            totalCapacity: selectedCapacity,
                            partySize: booking.partySize,
                            slack: selectedCapacity - booking.partySize,
                            zoneId: null,
                            tableNumbers: selectedTables,
                        },
                    } as ManualValidationResult);
                }
                if (error.status === 422 && error.details) {
                    const failedChecks = details?.checks?.filter((c) => !c.passed) ?? [];
                    const errorMessages = failedChecks.map((c) => `• ${c.message}`).join('\n') || error.message;
                    setErrorBanner(errorMessages);
                    toast({
                        title: 'Cannot assign tables',
                        description: errorMessages,
                        variant: 'destructive',
                        duration: 8000,
                    });
                    return;
                }

                // Other HTTP errors
                toast({
                    title: 'Assignment failed',
                    description: error.message,
                    variant: 'destructive',
                });
                setErrorBanner(error.message);
                return;
            }

            // Generic error handling
            const message = error instanceof Error ? error.message : 'Assignment failed';
            toast({
                title: 'Assignment failed',
                description: message,
                variant: 'destructive',
            });
            setErrorBanner(message);
        },
        onSuccess: async (_data, tableIds) => {
            // Clear local state
            setSelectedTables([]);
            setValidationResult(null);

            // Invalidate all related queries to ensure fresh data
            await Promise.all([
                // Refresh the manual assignment context
                refetchAssignmentContext(),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.assignmentContext(booking.id) }),
                // Invalidate the specific booking detail
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.detail(booking.id) }),
                // Invalidate the bookings list
                queryClient.invalidateQueries({ queryKey: queryKeys.bookings.list({}) }),
                // Invalidate ops bookings list
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.list({}) }),
            ]);

            // Notify parent component
            onAssignmentComplete?.();

            toast({
                title: 'Tables assigned',
                description: `Successfully assigned ${tableIds.length} table(s) to booking.`,
                duration: 3000,
            });
        },
    });

    // -- Handlers --
    const handleToggleTable = useCallback((tableId: string) => {
        setSelectedTables((prev) => {
            if (prev.includes(tableId)) return prev.filter((id) => id !== tableId);
            return [...prev, tableId];
        });
    }, []);

    // SIMPLIFIED: Single handler for direct assignment
    const handleAssign = useCallback(() => {
        if (assignedTables.length > 0) {
            const message = 'Tables are already assigned. Remove existing tables before assigning new ones.';
            setErrorBanner(message);
            toast({ title: 'Assignment blocked', description: message, variant: 'destructive' });
            return;
        }
        if (selectedTables.length === 0) {
            toast({ title: 'No tables selected', description: 'Please select tables to assign.', variant: 'destructive' });
            return;
        }

        setErrorBanner(null);
        directAssignMutation.mutate(selectedTables);
    }, [assignedTables.length, selectedTables, directAssignMutation, toast]);

    const handleClear = useCallback(() => {
        setSelectedTables([]);
        setValidationResult(null);
        // No holds in direct assignment system - just clear selection
    }, []);

    // No holds in direct assignment system - handleHoldExpired removed

    const handleUnassignConfirm = useCallback(async () => {
        if (!unassignTableId || !onUnassignTable) return;

        try {
            await onUnassignTable(unassignTableId);

            // Invalidate all related queries to ensure fresh data
            await Promise.all([
                refetchAssignmentContext(),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.assignmentContext(booking.id) }),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.detail(booking.id) }),
                queryClient.invalidateQueries({ queryKey: queryKeys.bookings.list({}) }),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.list({}) }),
            ]);

            // Notify parent component
            onAssignmentComplete?.();

            toast({
                title: 'Table removed',
                description: 'Table unassigned successfully. Data refreshed.',
            });
        } catch (error) {
            const message = error instanceof Error ? error.message : 'Failed to unassign table';
            toast({ title: 'Unassign failed', description: message, variant: 'destructive' });
        } finally {
            setUnassignTableId(null);
        }
    }, [unassignTableId, onUnassignTable, refetchAssignmentContext, queryClient, booking.id, onAssignmentComplete, toast]);

    // Handle removing ALL assigned tables (for merged table groups)
    const handleRemoveAllTables = useCallback(async () => {
        if (assignedTables.length === 0) return;

        const tableIds = assignedTables.map(t => t.id);

        try {
            // Use bulk unassign API
            await bookingService.unassignTablesDirect({
                bookingId: booking.id,
                tableIds,
            });

            // Invalidate all related queries
            await Promise.all([
                refetchAssignmentContext(),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.assignmentContext(booking.id) }),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.detail(booking.id) }),
                queryClient.invalidateQueries({ queryKey: queryKeys.bookings.list({}) }),
                queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.list({}) }),
            ]);

            // Notify parent component
            onAssignmentComplete?.();

            toast({
                title: 'All tables removed',
                description: `Successfully removed ${assignedTables.length} table(s). You can now re-assign fresh tables.`,
            });
        } catch (error) {
            const message = error instanceof Error ? error.message : 'Failed to remove tables';
            toast({ title: 'Remove failed', description: message, variant: 'destructive' });
        }
    }, [assignedTables, bookingService, booking.id, refetchAssignmentContext, queryClient, onAssignmentComplete, toast]);

    // -- Render Helpers --
    const isPending = assignmentContextLoading || directAssignMutation.isPending;
    const canAssign = selectedTables.length > 0 && !isPending && assignedTables.length === 0;

    // Clear validation when selection changes
    useEffect(() => {
        const prevSelection = prevSelectedTablesRef.current;
        const selectionChanged =
            prevSelection.length !== selectedTables.length ||
            !prevSelection.every(id => selectedTables.includes(id));

        if (selectionChanged && validationResult) {
            setValidationResult(null);
        }

        prevSelectedTablesRef.current = selectedTables;
    }, [selectedTables, validationResult]);

    // No active holds to sync in direct assignment system

    if (assignmentContextError) {
        const message = assignmentContextError instanceof Error ? assignmentContextError.message : 'Unknown error';
        return (
            <div className="flex flex-col items-center justify-center gap-4 p-8 rounded-xl border bg-destructive/5">
                <div className="flex items-center gap-2 text-destructive">
                    <AlertCircle className="h-5 w-5" />
                    <span className="font-medium">Error loading floor plan</span>
                </div>
                <p className="text-sm text-muted-foreground">{message}</p>
                <Button
                    onClick={() => refetchAssignmentContext()}
                    variant="outline"
                    size="sm"
                    className="gap-2"
                >
                    <RefreshCw className="h-4 w-4" />
                    Retry
                </Button>
            </div>
        );
    }

    return (
        <div className="grid h-full grid-cols-1 gap-4 lg:grid-cols-12">
            {errorBanner && (
                <Alert variant="destructive" className="lg:col-span-12">
                    <AlertDescription className="whitespace-pre-line text-sm">
                        {errorBanner}
                    </AlertDescription>
                </Alert>
            )}
            <div className="flex flex-col gap-4 lg:col-span-7">
                <AssignmentToolbar
                    selectedCount={effectiveSelectedIds.length}
                    selectedCapacity={selectedCapacity}
                    partySize={booking.partySize}
                    zoneId={validationResult?.summary?.zoneId}
                    validationChecks={validationChecks}
                    onAssign={handleAssign}
                    onClear={handleClear}
                    isPending={isPending}
                    isAssigning={directAssignMutation.isPending}
                    canAssign={canAssign}
                    assignDisabledReason={
                        selectedTables.length === 0
                            ? 'Select tables to assign'
                            : null
                    }
                    onlyAvailable={onlyAvailable}
                    onOnlyAvailableChange={setOnlyAvailable}
                />

                {validationChecks.length > 0 && <ValidationChecks checks={validationChecks} />}

                <div
                    className="flex-1 overflow-hidden rounded-xl border bg-muted/10 relative min-h-[400px]"
                    role="region"
                    aria-label="Table floor plan"
                >
                    {assignmentContextLoading ? (
                        <div className="p-6" role="status" aria-live="polite">
                            <div className="grid gap-4 grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6">
                                {Array.from({ length: 18 }).map((_, i) => (
                                    <div
                                        key={i}
                                        className="aspect-square rounded-xl bg-muted/50 animate-pulse"
                                        style={{ animationDelay: `${i * 30}ms` }}
                                    />
                                ))}
                            </div>
                            <span className="sr-only">Loading floor plan...</span>
                        </div>
                    ) : assignmentContext && assignmentContext.tables.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-full gap-6 p-8">
                            <div className="flex h-20 w-20 items-center justify-center rounded-full bg-gradient-to-br from-muted/50 to-muted/30 border-2 border-muted">
                                <LayoutGrid className="h-10 w-10 text-muted-foreground" strokeWidth={1.5} />
                            </div>
                            <div className="text-center space-y-2 max-w-md">
                                <h3 className="text-xl font-semibold text-foreground">No tables available</h3>
                                <p className="text-sm text-muted-foreground leading-relaxed">
                                    There are no tables configured for this restaurant. Contact your administrator to set up table inventory.
                                </p>
                            </div>
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={() => refetchAssignmentContext()}
                                className="gap-2"
                            >
                                <RefreshCw className="h-4 w-4" />
                                Refresh
                            </Button>
                        </div>
                    ) : (
                        <div className="absolute inset-0 overflow-auto p-2 sm:p-4">
                            <TableFloorPlan
                                bookingId={booking.id}
                                tables={assignmentContext?.tables ?? []}
                                holds={assignmentContext?.holds ?? []}
                                conflicts={assignmentContext?.conflicts ?? []}
                                bookingAssignments={assignmentContext?.bookingAssignments ?? []}
                                selectedTableIds={selectedTables}
                                onToggle={handleToggleTable}
                                disabled={isPending}
                                onlyAvailable={onlyAvailable}
                                className="min-w-[320px] sm:min-w-[500px] md:min-w-[600px]"
                            />
                        </div>
                    )}
                </div>
            </div>

            <div className="flex flex-col gap-4 lg:col-span-5">
                {assignedTables.length > 0 ? (
                    <div
                        className="space-y-4 rounded-xl border bg-background p-4 shadow-sm animate-in fade-in-50"
                        role="region"
                        aria-label="Currently assigned tables"
                    >
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-emerald-100 to-emerald-50 dark:from-emerald-900/40 dark:to-emerald-900/20 border-2 border-emerald-200/50 dark:border-emerald-800/50 shadow-sm">
                                    <CheckCircle2 className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                                </div>
                                <div>
                                    <h4 className="text-base font-semibold text-foreground">Assigned Tables</h4>
                                    <p className="text-xs text-muted-foreground">
                                        {assignedTables.reduce((sum, t) => sum + t.capacity, 0)} total seats
                                    </p>
                                </div>
                                <Badge variant="outline" className="font-mono text-xs px-2 py-1">
                                    {assignedTables.length} {assignedTables.length === 1 ? 'table' : 'tables'}
                                </Badge>
                            </div>

                            {assignedTables.length > 1 && (
                                <Button
                                    variant="outline"
                                    size="default"
                                    className="h-10 text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30 font-medium"
                                    onClick={handleRemoveAllTables}
                                    aria-label="Remove all assigned tables"
                                >
                                    <Trash2 className="mr-2 h-4 w-4" />
                                    Remove All
                                </Button>
                            )}
                        </div>

                        <div className="grid gap-3 sm:grid-cols-2">
                            {assignedTables.map((table, idx) => (
                                <div
                                    key={table.id}
                                    className="group relative rounded-xl border-2 border-primary/20 bg-gradient-to-br from-primary/5 via-primary/3 to-transparent p-4 shadow-sm transition-all duration-200 hover:shadow-md hover:border-primary/40 hover:-translate-y-0.5 animate-in fade-in-50 slide-in-from-bottom-2"
                                    style={{ animationDelay: `${idx * 50}ms` }}
                                >
                                    <div className="absolute top-3 right-3">
                                        <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-gradient-to-br from-primary/20 to-primary/10 border border-primary/20">
                                            <LayoutGrid className="h-5 w-5 text-primary" strokeWidth={2} />
                                        </div>
                                    </div>

                                    <div className="space-y-3 pr-14">
                                        <div>
                                            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Table</p>
                                            <p className="text-3xl font-bold text-foreground tabular-nums">{table.tableNumber}</p>
                                        </div>

                                        <div className="space-y-2">
                                            <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                                <div className="flex h-6 w-6 items-center justify-center rounded-md bg-muted/50">
                                                    <Users className="h-4 w-4" />
                                                </div>
                                                <span className="font-medium">{table.capacity} seats</span>
                                            </div>
                                            {table.section && (
                                                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                                    <div className="flex h-6 w-6 items-center justify-center rounded-md bg-muted/50">
                                                        <MapPin className="h-4 w-4" />
                                                    </div>
                                                    <span className="font-medium">{table.section}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {assignedTables.length === 1 && onUnassignTable && (
                                        <Button
                                            variant="outline"
                                            size="sm"
                                            className="mt-4 w-full h-9 text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30 font-medium"
                                            onClick={() => setUnassignTableId(table.id)}
                                            aria-label={`Remove table ${table.tableNumber} from booking`}
                                        >
                                            <X className="mr-2 h-4 w-4" />
                                            Remove Table
                                        </Button>
                                    )}
                                </div>
                            ))}
                        </div>

                        {assignedTables.length > 1 && (
                            <Alert className="border-blue-200 bg-gradient-to-r from-blue-50 to-blue-50/50 dark:from-blue-900/20 dark:to-blue-900/10 dark:border-blue-800/50">
                                <Info className="h-4 w-4 text-blue-600 dark:text-blue-400" />
                                <AlertDescription className="text-sm text-blue-900 dark:text-blue-100 leading-relaxed">
                                    💡 <strong>Merged tables:</strong> These tables are combined to meet capacity requirements. Use &quot;Remove All&quot; to unassign and select fresh tables.
                                </AlertDescription>
                            </Alert>
                        )}
                    </div>
                ) : (
                    <div className="rounded-xl border bg-muted/10 p-4 text-sm text-muted-foreground shadow-sm">
                        No tables assigned yet. Select tables on the left to match the party size.
                    </div>
                )}
            </div>

            {/* Unassign Confirmation Dialog */}
            <AlertDialog open={Boolean(unassignTableId)} onOpenChange={(open) => !open && setUnassignTableId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Remove table assignment?</AlertDialogTitle>
                        <AlertDialogDescription>
                            Are you sure you want to remove this table from the booking? This action cannot be undone.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction onClick={handleUnassignConfirm} className="bg-destructive hover:bg-destructive/90">
                            Remove
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

'use client';

import { useQueryClient } from '@tanstack/react-query';
import { AlertCircle, Calendar as CalendarIcon, Clock, LayoutGrid, Users, Mail, Phone, Hash, Info } from 'lucide-react';
import { useCallback, useMemo } from 'react';

import { BookingAssignmentTabContent } from '@/components/features/dashboard/booking-details/BookingAssignmentTabContent';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogTrigger } from '@/components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useBookingState } from '@/contexts/booking-state-machine';
import { queryKeys } from '@/lib/query/keys';
import { cn } from '@/lib/utils';
import { formatDateReadable, formatTimeRange, getTodayInTimezone } from '@/lib/utils/datetime';

import {
  BookingHistoryDialog,
  BookingOverviewTab,
  KeyboardShortcutsDialog,
} from './components';
import { useBookingCountdown, useBookingDialogState, useKeyboardShortcuts } from './hooks';

import type { BookingDetailsDialogProps, BookingDetailsTab } from './types';

/**
 * Main BookingDetailsDialog component
 * 
 * SOLID Principles Applied:
 * - SRP: Orchestrates child components, each with single responsibility
 * - OCP: New tabs/dialogs can be added via composition
 * - DIP: Depends on abstractions (props interfaces)
 * - ISP: Props are scoped per child component needs
 */
export function BookingDetailsDialog({
  booking,
  summary,
  allowTableAssignments,
  onCheckIn,
  onCheckOut,
  onMarkNoShow,
  onUndoNoShow,
  pendingLifecycleAction,
  onUnassignTable,
  open,
  onOpenChange,
}: BookingDetailsDialogProps) {
  const queryClient = useQueryClient();
  const supportsTableAssignment = allowTableAssignments;

  // --- State Management (SRP: Dialog state in dedicated hook) ---
  const dialogState = useBookingDialogState({
    open,
    onOpenChange,
    supportsTableAssignment,
  });

  // --- Time Intelligence (SRP: Countdown logic in dedicated hook) ---
  const countdown = useBookingCountdown({
    startTime: booking.startTime,
    date: summary.date,
    timezone: summary.timezone,
    checkedInAt: booking.checkedInAt,
  });

  // --- Derived State ---
  const bookingState = useBookingState(booking.id);
  const effectiveStatus = bookingState.effectiveStatus ?? booking.status;
  const lifecyclePending = pendingLifecycleAction ?? dialogState.localPendingAction;
  const isCancelled = effectiveStatus === 'cancelled';

  const lifecycleAvailability = useMemo(() => {
    const isToday = getTodayInTimezone(summary.timezone) === summary.date;
    return {
      isToday,
      reason: isToday ? undefined : 'Past date · Status locked',
    };
  }, [summary.date, summary.timezone]);

  const assignedCapacity = useMemo(() => {
    return (booking.tableAssignments ?? []).reduce((sum, group) => {
      if (typeof group.capacitySum === 'number') return sum + group.capacitySum;
      const membersCapacity = group.members.reduce((s, m) => s + (m.capacity ?? 0), 0);
      return sum + membersCapacity;
    }, 0);
  }, [booking.tableAssignments]);

  const assignedTablesCount = useMemo(() => {
    return (booking.tableAssignments ?? []).reduce((sum, group) => sum + group.members.length, 0);
  }, [booking.tableAssignments]);

  const capacityDelta = assignedCapacity - booking.partySize;

  const refLabel = booking.reference ?? booking.id;
  const refShort = refLabel.length > 10 ? `${refLabel.slice(0, 6)}…${refLabel.slice(-4)}` : refLabel;
  const serviceDateReadable = formatDateReadable(summary.date, summary.timezone);
  const serviceTimeLabel = formatTimeRange(booking.startTime, booking.endTime, summary.timezone);

  const SummaryStat = ({
    icon: Icon,
    label,
    value,
    helper,
    tone,
  }: {
    icon: React.ComponentType<{ className?: string }>;
    label: string;
    value: string;
    helper?: string;
    tone?: 'positive' | 'negative';
  }) => (
    <div
      className={cn(
        'flex flex-col gap-1 rounded-xl border px-3 py-2 shadow-sm bg-background/80',
        tone === 'positive' && 'border-emerald-200 bg-emerald-50/60 text-emerald-700',
        tone === 'negative' && 'border-red-200 bg-red-50/60 text-red-700'
      )}
    >
      <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        <Icon className="h-4 w-4" />
        {label}
      </div>
      <div className="text-2xl font-bold leading-tight text-foreground">{value}</div>
      {helper ? <div className="text-xs text-muted-foreground">{helper}</div> : null}
    </div>
  );

  // --- Lifecycle Action Handlers (SRP: Action execution) ---
  const handleCheckIn = useCallback(async () => {
    if (!onCheckIn) return;
    // If PRIORITY_WAITLIST, switch to tables tab
    if (effectiveStatus === 'PRIORITY_WAITLIST') {
      dialogState.setActiveTab('tables');
      dialogState.setLocalPendingAction(null);
      return;
    }
    dialogState.setLocalPendingAction('check-in');
    try {
      await onCheckIn();
    } finally {
      dialogState.setLocalPendingAction(null);
    }
  }, [onCheckIn, effectiveStatus, dialogState]);

  const handleCheckOut = useCallback(async () => {
    if (!onCheckOut) return;
    dialogState.setLocalPendingAction('check-out');
    try {
      await onCheckOut();
    } finally {
      dialogState.setLocalPendingAction(null);
    }
  }, [onCheckOut, dialogState]);

  const handleMarkNoShow = useCallback(
    async (options?: { performedAt?: string | null; reason?: string | null }) => {
      if (!onMarkNoShow) return;
      dialogState.setLocalPendingAction('no-show');
      try {
        await onMarkNoShow(options);
      } finally {
        dialogState.setLocalPendingAction(null);
      }
    },
    [onMarkNoShow, dialogState]
  );

  const handleUndoNoShow = useCallback(
    async (reason?: string | null) => {
      if (!onUndoNoShow) return;
      dialogState.setLocalPendingAction('undo-no-show');
      try {
        await onUndoNoShow(reason);
      } finally {
        dialogState.setLocalPendingAction(null);
      }
    },
    [onUndoNoShow, dialogState]
  );

  // --- Keyboard Shortcuts (SRP: Keyboard handling in dedicated hook) ---
  useKeyboardShortcuts({
    isOpen: dialogState.isOpen,
    effectiveStatus,
    isPending: Boolean(lifecyclePending),
    showShortcuts: dialogState.showShortcuts,
    setShowShortcuts: dialogState.setShowShortcuts,
    closeDialog: () => dialogState.setIsOpen(false),
    handlers: {
      handleCheckIn,
      handleCheckOut,
      handleMarkNoShow,
      handleUndoNoShow,
    },
  });

  // --- Event Handlers ---
  const handleAssignmentComplete = useCallback(() => {
    void queryClient.invalidateQueries({ queryKey: queryKeys.opsBookings.detail(booking.id) });
  }, [queryClient, booking.id]);

  // Determine if controlled mode
  const isControlled = open !== undefined;

  return (
    <>
      <Dialog open={dialogState.isOpen} onOpenChange={dialogState.setIsOpen}>
        {!isControlled && (
          <DialogTrigger asChild>
            <Button variant="outline" size="sm" className="h-11 min-w-[100px] touch-manipulation">
              Details
            </Button>
          </DialogTrigger>
        )}

        <DialogContent className="max-w-[1200px] max-h-[90vh] overflow-hidden p-0 gap-0">
          <div className="flex h-full flex-col overflow-hidden">
            {/* Hero / Summary */}
            <div className="border-b bg-muted/40 px-6 py-4">
              <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                <div className="flex items-start gap-4">
                  <div className="flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-primary/20 via-primary/15 to-primary/10 border-2 border-primary/30 text-lg font-bold text-primary shadow-sm">
                    {booking.customerName
                      .split(' ')
                      .map((n) => n[0])
                      .join('')
                      .slice(0, 2)
                      .toUpperCase()}
                  </div>
                  <div className="space-y-2">
                    <div className="flex flex-wrap items-center gap-2">
                      <h2 className="text-lg font-semibold text-foreground">{booking.customerName}</h2>
                      <Badge variant="outline" className="px-3 py-1 text-xs font-semibold">
                        {booking.loyaltyTier ?? 'Guest'}
                      </Badge>
                      <Badge variant="secondary" className="gap-1">
                        <Hash className="h-3.5 w-3.5" /> {refShort}
                      </Badge>
                      {booking.source && (
                        <Badge variant="outline" className="gap-1">
                          <Info className="h-3.5 w-3.5" /> {booking.source}
                        </Badge>
                      )}
                    </div>
                    <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
                      <span className="inline-flex items-center gap-1">
                        <CalendarIcon className="h-4 w-4" /> {serviceDateReadable}
                      </span>
                      <span className="text-muted-foreground">·</span>
                      <span className="inline-flex items-center gap-1">
                        <Clock className="h-4 w-4" /> {serviceTimeLabel}
                      </span>
                      <span className="text-muted-foreground">·</span>
                      <Badge variant="secondary" className="capitalize">
                        {effectiveStatus.replace('_', ' ')}
                      </Badge>
                    </div>
                    <div className="flex flex-wrap gap-2 text-sm text-foreground/80">
                      {booking.customerEmail && (
                        <a
                          href={`mailto:${booking.customerEmail}`}
                          className="inline-flex items-center gap-1 rounded-full bg-secondary px-3 py-1 hover:bg-secondary/80 transition"
                        >
                          <Mail className="h-3.5 w-3.5" /> {booking.customerEmail}
                        </a>
                      )}
                      {booking.customerPhone && (
                        <a
                          href={`tel:${booking.customerPhone.replace(/[^+\d]/g, '')}`}
                          className="inline-flex items-center gap-1 rounded-full bg-secondary px-3 py-1 hover:bg-secondary/80 transition"
                        >
                          <Phone className="h-3.5 w-3.5" /> {booking.customerPhone}
                        </a>
                      )}
                      {booking.seatingPreference && (
                        <Badge variant="outline" className="gap-1">
                          Preference: {booking.seatingPreference}
                        </Badge>
                      )}
                    </div>
                  </div>
                </div>

                <div className="grid w-full max-w-xl grid-cols-2 gap-3 sm:grid-cols-4">
                  <SummaryStat icon={Users} label="Party" value={`${booking.partySize}`} />
                  <SummaryStat icon={LayoutGrid} label="Tables" value={`${assignedTablesCount}`} helper="assigned" />
                  <SummaryStat icon={LayoutGrid} label="Capacity" value={`${assignedCapacity}`} helper="seats" />
                  <SummaryStat
                    icon={AlertCircle}
                    label="Delta"
                    value={`${capacityDelta >= 0 ? '+' : ''}${capacityDelta}`}
                    helper="vs party"
                    tone={capacityDelta >= 0 ? 'positive' : 'negative'}
                  />
                </div>
              </div>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto px-6 py-4">
              <Tabs
                value={dialogState.activeTab}
                onValueChange={(value) => dialogState.setActiveTab(value as BookingDetailsTab)}
                className="space-y-4"
              >
                <TabsList className={cn('grid w-full gap-2', supportsTableAssignment ? 'grid-cols-2' : 'grid-cols-1')}>
                  <TabsTrigger value="overview" className="text-sm font-medium">
                    Overview
                  </TabsTrigger>
                  {supportsTableAssignment && (
                    <TabsTrigger value="tables" className="text-sm font-medium">
                      Tables
                    </TabsTrigger>
                  )}
                </TabsList>

                <TabsContent value="overview" className="focus-visible:outline-none animate-in fade-in-50 slide-in-from-bottom-2">
                  <BookingOverviewTab
                    booking={booking}
                    summary={summary}
                    effectiveStatus={effectiveStatus}
                    isCancelled={isCancelled}
                    supportsTableAssignment={supportsTableAssignment}
                    lifecycleAvailability={lifecycleAvailability}
                    lifecyclePending={lifecyclePending}
                    relativeStartTime={countdown.relativeStartTime}
                    checkedInRelativeTime={countdown.checkedInRelativeTime}
                    onCheckIn={handleCheckIn}
                    onCheckOut={handleCheckOut}
                    onMarkNoShow={handleMarkNoShow}
                    onUndoNoShow={handleUndoNoShow}
                  />
                </TabsContent>

                {supportsTableAssignment && (
                  <TabsContent value="tables" className="mt-0 h-full data-[state=active]:block">
                    <BookingAssignmentTabContent
                      booking={booking}
                      restaurantId={summary.restaurantId}
                      date={summary.date}
                      onUnassignTable={onUnassignTable}
                      onAssignmentComplete={handleAssignmentComplete}
                    />
                  </TabsContent>
                )}
              </Tabs>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* History Dialog (SRP: History display) */}
      <BookingHistoryDialog
        open={dialogState.isHistoryOpen}
        onOpenChange={dialogState.setIsHistoryOpen}
        bookingId={booking.id}
        timezone={summary.timezone}
      />

      {/* Keyboard Shortcuts Dialog (SRP: Shortcuts display) */}
      <KeyboardShortcutsDialog
        open={dialogState.showShortcuts}
        onOpenChange={dialogState.setShowShortcuts}
      />
    </>
  );
}

'use client';

import { Calendar as CalendarIcon, Clock, History, Keyboard, MoreHorizontal } from 'lucide-react';

import { BookingStatusBadge, StatusTransitionAnimator } from '@/components/features/booking-state-machine';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { useBookingState } from '@/contexts/booking-state-machine';
import { cn } from '@/lib/utils';
import { formatDateReadable, formatTimeRange } from '@/lib/utils/datetime';
import { formatCountdown } from '@/lib/utils/relative-time';

import { COUNTDOWN_THRESHOLDS } from '../constants';

import type { BookingHeaderProps } from '../types';

/**
 * Booking header with status, date/time, and actions menu
 * Single Responsibility: Display booking header information and actions
 */
export function BookingHeader({
  booking,
  summary,
  effectiveStatus,
  minutesRemaining,
  timeStatus,
  checkedInRelativeTime,
  supportsTableAssignment,
  onOpenHistory,
  onOpenShortcuts,
}: BookingHeaderProps) {
  const bookingState = useBookingState(booking.id);

  const serviceDateReadable = formatDateReadable(summary.date, summary.timezone);
  const serviceTime = formatTimeRange(booking.startTime, booking.endTime, summary.timezone);

  const showCountdown =
    minutesRemaining !== null &&
    timeStatus !== 'past' &&
    minutesRemaining <= COUNTDOWN_THRESHOLDS.showCountdown;

  return (
    <div className="flex flex-col gap-4 border-b p-6">
      <div className="flex items-start justify-between">
        <div className="space-y-1">
          <div className="flex items-center gap-2 text-lg font-medium text-foreground">
            <CalendarIcon className="h-5 w-5 text-muted-foreground" />
            <span>{serviceDateReadable}</span>
            <span className="text-muted-foreground">·</span>
            <Clock className="h-5 w-5 text-muted-foreground" />
            <span>{serviceTime}</span>
          </div>
          <div className="flex items-center gap-2">
            {/* Countdown Timer */}
            {showCountdown ? (
              <Badge
                variant="outline"
                className={cn(
                  'font-medium',
                  timeStatus === 'imminent'
                    ? 'animate-pulse border-orange-500 bg-orange-100 text-orange-900'
                    : 'border-blue-500 bg-blue-100 text-blue-900'
                )}
              >
                Starts in {formatCountdown(minutesRemaining)}
              </Badge>
            ) : null}

            {checkedInRelativeTime && (
              <span className="text-sm text-muted-foreground">
                Checked in {checkedInRelativeTime}
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <StatusTransitionAnimator
            status={bookingState.status}
            effectiveStatus={bookingState.effectiveStatus}
            isTransitioning={bookingState.isTransitioning}
            className="inline-flex rounded-full"
            overlayClassName="inline-flex"
          >
            <BookingStatusBadge status={effectiveStatus} className="h-8 px-3 text-sm" />
          </StatusTransitionAnimator>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="h-8 w-8">
                <MoreHorizontal className="h-4 w-4" />
                <span className="sr-only">More options</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
              <DropdownMenuLabel>Actions</DropdownMenuLabel>
              <DropdownMenuItem onClick={onOpenHistory}>
                <History className="mr-2 h-4 w-4" />
                View history
              </DropdownMenuItem>
              {supportsTableAssignment && (
                <DropdownMenuItem onClick={onOpenShortcuts}>
                  <Keyboard className="mr-2 h-4 w-4" />
                  Keyboard shortcuts
                </DropdownMenuItem>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useQuery } from '@tanstack/react-query';
import { format } from 'date-fns';
import { ArrowRight, Loader2 } from 'lucide-react';

import { BookingStatusBadge } from '@/components/features/booking-state-machine';
import { Badge } from '@/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { useBookingService } from '@/contexts/ops-services';
import { queryKeys } from '@/lib/query/keys';

import type { BookingHistoryDialogProps } from '../types';

/**
 * Dialog for displaying booking lifecycle history
 * Single Responsibility: Display booking history entries
 */
export function BookingHistoryDialog({
  open,
  onOpenChange,
  bookingId,
  timezone: _timezone,
}: BookingHistoryDialogProps) {
  const bookingService = useBookingService();

  const {
    data: historyData,
    isLoading: historyLoading,
    isError: historyError,
    error: historyErrorObject,
    refetch: refetchHistory,
  } = useQuery({
    queryKey: queryKeys.bookings.history(bookingId),
    queryFn: async () => bookingService.getBookingHistory(bookingId),
    enabled: open,
    staleTime: 60_000,
  });

  const historyEntries = historyData?.entries ?? [];
  const historyErrorMessage =
    historyErrorObject instanceof Error ? historyErrorObject.message : 'Unable to load history';

  const formatHistoryDate = (iso: string | null | undefined) => {
    if (!iso) return null;
    const parsed = new Date(iso);
    if (Number.isNaN(parsed.getTime())) return null;
    return format(parsed, 'dd MMM yyyy, HH:mm');
  };

  const getMetadataString = (
    metadata: Record<string, unknown>,
    key: string
  ): string | null => {
    const value = metadata?.[key as keyof typeof metadata];
    return typeof value === 'string' && value.length > 0 ? value : null;
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(isOpen) => {
        onOpenChange(isOpen);
        if (isOpen) {
          void refetchHistory();
        }
      }}
    >
      <DialogContent className="max-w-lg max-h-[70vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Booking history</DialogTitle>
          <DialogDescription>
            Lifecycle changes recorded for this reservation.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-3 py-2">
          {historyLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> Loading history…
            </div>
          ) : historyError ? (
            <p className="text-sm text-destructive">{historyErrorMessage}</p>
          ) : historyEntries.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No lifecycle changes have been recorded yet.
            </p>
          ) : (
            historyEntries.map((entry) => {
              const actorLabel = entry.actor?.name ?? entry.actor?.email ?? 'System';
              const actionValue = getMetadataString(entry.metadata, 'action');
              const actionLabel = actionValue ? actionValue.replace(/[-_]/g, ' ') : null;
              const performedAtLabel = formatHistoryDate(
                getMetadataString(entry.metadata, 'performedAt')
              );
              const changedAtLabel = formatHistoryDate(entry.changedAt) ?? entry.changedAt;

              return (
                <div
                  key={entry.id}
                  className="rounded-xl border border-border/60 bg-muted/10 p-3"
                >
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-2">
                      {entry.fromStatus ? (
                        <BookingStatusBadge status={entry.fromStatus} size="sm" showTooltip />
                      ) : (
                        <Badge
                          variant="outline"
                          className="text-xs font-semibold uppercase tracking-wide"
                        >
                          New
                        </Badge>
                      )}
                      <ArrowRight
                        className="h-3.5 w-3.5 text-muted-foreground"
                        aria-hidden
                      />
                      <BookingStatusBadge status={entry.toStatus} size="sm" showTooltip />
                    </div>
                    <span className="text-xs text-muted-foreground">{changedAtLabel}</span>
                  </div>
                  <p className="mt-2 text-sm font-semibold text-foreground">{actorLabel}</p>
                  {actionLabel ? (
                    <p className="text-xs uppercase tracking-wide text-muted-foreground">
                      Action: {actionLabel}
                    </p>
                  ) : null}
                  {entry.reason ? (
                    <p className="mt-1 text-sm text-muted-foreground">Reason: {entry.reason}</p>
                  ) : null}
                  {performedAtLabel ? (
                    <p className="mt-1 text-xs text-muted-foreground">
                      Performed at: {performedAtLabel}
                    </p>
                  ) : null}
                </div>
              );
            })
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { Calendar as CalendarIcon, Clock, LogIn, Users } from 'lucide-react';

import { BookingActionButton } from '@/components/features/booking-state-machine';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { formatDateReadable, formatTimeRange } from '@/lib/utils/datetime';

import { DetailCard } from './DetailCard';

import type { BookingOverviewTabProps } from '../types';

/**
 * Overview tab content with quick actions and booking details
 * Single Responsibility: Display booking overview and action controls
 */
export function BookingOverviewTab({
  booking,
  summary,
  effectiveStatus: _effectiveStatus,
  isCancelled,
  supportsTableAssignment,
  lifecycleAvailability,
  lifecyclePending,
  relativeStartTime,
  checkedInRelativeTime,
  onCheckIn,
  onCheckOut,
  onMarkNoShow,
  onUndoNoShow,
}: BookingOverviewTabProps) {
  const serviceDateReadable = formatDateReadable(summary.date, summary.timezone);
  const serviceTime = formatTimeRange(booking.startTime, booking.endTime, summary.timezone);

  const formatLifecycleTimestamp = (iso: string | null) => {
    if (!iso) return 'Not yet';
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) return 'Not yet';
    const formatter = new Intl.DateTimeFormat('en-GB', {
      timeZone: summary.timezone,
      day: 'numeric',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit',
    });
    return formatter.format(date);
  };

  return (
    <div className="grid gap-6">
      {/* Quick Actions Card */}
      <Card className="border-none bg-secondary/30 shadow-none">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-medium">Quick Actions</CardTitle>
          <CardDescription>Manage arrival status and booking lifecycle.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <BookingActionButton
            booking={booking}
            pendingAction={lifecyclePending}
            onCheckIn={onCheckIn}
            onCheckOut={onCheckOut}
            onMarkNoShow={onMarkNoShow}
            onUndoNoShow={onUndoNoShow}
            showConfirmation
            lifecycleAvailability={lifecycleAvailability}
          />
          {isCancelled ? (
            <Alert variant="destructive" className="border-destructive/20 bg-destructive/5">
              <AlertTitle>Booking cancelled</AlertTitle>
              <AlertDescription>
                Status changes are disabled for cancelled reservations.
              </AlertDescription>
            </Alert>
          ) : null}
          {!supportsTableAssignment ? (
            <Alert className="border-muted bg-muted/50">
              <AlertTitle>Past service date</AlertTitle>
              <AlertDescription>Table assignment changes are locked.</AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      {/* Booking Details Grid */}
      <div className="grid gap-4 sm:grid-cols-2">
        <DetailCard
          icon={Users}
          label="Guests"
          value={`${booking.partySize} ${booking.partySize === 1 ? 'guest' : 'guests'}`}
        />
        <DetailCard icon={CalendarIcon} label="Date" value={serviceDateReadable} />
        <DetailCard
          icon={Clock}
          label="Time"
          value={serviceTime}
          relativeTime={relativeStartTime || undefined}
        />
        <DetailCard
          icon={LogIn}
          label="Checked In"
          value={formatLifecycleTimestamp(booking.checkedInAt)}
          relativeTime={checkedInRelativeTime || undefined}
        />
      </div>
    </div>
  );
}

'use client';

import { ExternalLink } from 'lucide-react';

import { CopyButton } from '@/components/ui/copy-button';
import { cn } from '@/lib/utils';

import type { DetailCardProps } from '../types';

/**
 * Reusable detail card component for displaying labeled information
 * Single Responsibility: Display a single piece of detail information
 */
export function DetailCard({
  icon: Icon,
  label,
  value,
  href,
  actionLabel,
  copyable,
  relativeTime,
  compact,
}: DetailCardProps) {
  const showCopyButton = copyable && value && value !== 'Not provided';
  const isExternal = href?.startsWith('http');

  const content = (
    <div className={cn('flex items-start gap-3', compact ? 'p-3' : 'p-4')}>
      <div className={cn('rounded-lg bg-primary/10', compact ? 'p-2' : 'p-2.5')}>
        <Icon
          className={cn('text-primary', compact ? 'h-3.5 w-3.5' : 'h-4 w-4')}
          aria-hidden
        />
      </div>
      <div className="flex min-w-0 flex-1 flex-col">
        <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
          {label}
        </span>
        <span
          className={cn(
            'truncate font-semibold text-foreground',
            compact ? 'text-sm' : 'text-base'
          )}
        >
          {value}
        </span>
        {relativeTime ? (
          <span className="mt-0.5 text-xs text-muted-foreground">{relativeTime}</span>
        ) : null}
        {href && actionLabel ? (
          <span className="mt-1 flex items-center gap-1 text-xs font-medium text-primary group-hover:underline">
            {actionLabel}
            {isExternal ? <ExternalLink className="h-3 w-3" /> : null}
