'use client';

import { DateTime } from 'luxon';
import { useMemo } from 'react';

import { useCountdown } from '@/hooks/use-countdown';
import { formatRelativeTime } from '@/lib/utils/relative-time';

import type { BookingCountdownState } from '../types';

type UseBookingCountdownOptions = {
  /** Booking start time (ISO string or time string) */
  startTime: string | null;
  /** Service date in YYYY-MM-DD format */
  date: string;
  /** Restaurant timezone */
  timezone: string;
  /** When the guest checked in (ISO timestamp) */
  checkedInAt: string | null;
};

/**
 * Hook for managing booking countdown and time-related state
 * Single Responsibility: Time intelligence only
 */
export function useBookingCountdown({
  startTime,
  date,
  timezone,
  checkedInAt,
}: UseBookingCountdownOptions): BookingCountdownState {
  // Parse booking start time into DateTime
  const bookingStartTime = useMemo(() => {
    if (!startTime) return null;

    const dateTime = DateTime.fromISO(
      /^[0-9]{4}-[0-9]{2}-[0-9]{2}T/.test(startTime) ? startTime : `${date}T${startTime}`,
      { zone: timezone }
    );

    return dateTime.isValid ? dateTime : null;
  }, [startTime, date, timezone]);

  // Use the countdown hook
  const { minutesRemaining, timeStatus } = useCountdown(bookingStartTime);

  // Format relative start time
  const relativeStartTime = useMemo(() => {
    if (!bookingStartTime) return null;
    const now = DateTime.now().setZone(timezone);
    return formatRelativeTime(bookingStartTime, now, { style: 'long' });
  }, [bookingStartTime, timezone]);

  // Format checked-in relative time
  const checkedInRelativeTime = useMemo(() => {
    if (!checkedInAt) return null;
    const checkedInTime = DateTime.fromISO(checkedInAt);
    if (!checkedInTime.isValid) return null;
    const now = DateTime.now();
    return formatRelativeTime(checkedInTime, now, { style: 'long' });
  }, [checkedInAt]);

  return {
    minutesRemaining,
    timeStatus,
    relativeStartTime,
    checkedInRelativeTime,
  };
}

'use client';

import { useCallback, useState } from 'react';

import type { BookingDetailsTab, BookingDialogState } from '../types';
import type { BookingAction } from '@/components/features/booking-state-machine';

type UseBookingDialogStateOptions = {
  /** External controlled open state */
  open?: boolean;
  /** External controlled open change handler */
  onOpenChange?: (open: boolean) => void;
  /** Whether table assignments are supported (affects tab visibility) */
  supportsTableAssignment?: boolean;
};

/**
 * Hook for managing BookingDetailsDialog state
 * Single Responsibility: Dialog state management only
 */
export function useBookingDialogState({
  open,
  onOpenChange,
  supportsTableAssignment = false,
}: UseBookingDialogStateOptions = {}): BookingDialogState {
  // Internal state for uncontrolled mode
  const [internalIsOpen, setInternalIsOpen] = useState(false);
  const [activeTab, setActiveTabState] = useState<BookingDetailsTab>('overview');
  const [showShortcuts, setShowShortcuts] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [localPendingAction, setLocalPendingAction] = useState<BookingAction | null>(null);

  // Determine if we're in controlled mode
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalIsOpen;

  // Unified setter that works in both modes
  const setIsOpen = useCallback(
    (value: boolean) => {
      if (isControlled) {
        onOpenChange?.(value);
      } else {
        setInternalIsOpen(value);
      }

      // Reset local pending action when dialog closes
      if (!value) {
        setLocalPendingAction(null);
      }
    },
    [isControlled, onOpenChange]
  );

  // Tab setter with validation
  const setActiveTab = useCallback(
    (tab: BookingDetailsTab) => {
      // Prevent switching to tables tab if not supported
      if (tab === 'tables' && !supportsTableAssignment) {
        return;
      }
      setActiveTabState(tab);
    },
    [supportsTableAssignment]
  );

  return {
    isOpen,
    setIsOpen,
    activeTab,
    setActiveTab,
    showShortcuts,
    setShowShortcuts,
    isHistoryOpen,
    setIsHistoryOpen,
    localPendingAction,
    setLocalPendingAction,
  };
}

'use client';

import { useCallback, useEffect } from 'react';

import { KEYBOARD_SHORTCUTS } from '../constants';

import type { LifecycleActionHandlers } from '../types';
import type { BookingAction } from '@/components/features/booking-state-machine';

type UseKeyboardShortcutsOptions = {
  /** Whether the dialog is open */
  isOpen: boolean;
  /** Current effective booking status */
  effectiveStatus: string;
  /** Whether a lifecycle action is pending */
  isPending: boolean;
  /** Whether shortcuts help is showing */
  showShortcuts: boolean;
  /** Setter for shortcuts help visibility */
  setShowShortcuts: (show: boolean) => void;
  /** Close the dialog */
  closeDialog: () => void;
  /** Lifecycle action handlers */
  handlers: LifecycleActionHandlers;
};

/**
 * Hook for managing keyboard shortcuts in BookingDetailsDialog
 * Single Responsibility: Keyboard interaction handling only
 */
export function useKeyboardShortcuts({
  isOpen,
  effectiveStatus,
  isPending,
  showShortcuts,
  setShowShortcuts,
  closeDialog,
  handlers,
}: UseKeyboardShortcutsOptions): void {
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (!isOpen) return;
      if (event.defaultPrevented) return;
      if (event.metaKey || event.ctrlKey || event.altKey) return;

      // Ignore if focused on input elements
      const target = event.target as HTMLElement | null;
      if (target) {
        const tagName = target.tagName;
        if (
          tagName === 'INPUT' ||
          tagName === 'TEXTAREA' ||
          tagName === 'SELECT' ||
          target.isContentEditable
        ) {
          return;
        }
      }

      // Handle Escape key
      if (event.key === 'Escape') {
        event.preventDefault();
        if (showShortcuts) {
          setShowShortcuts(false);
        } else {
          closeDialog();
        }
        return;
      }

      // Handle help shortcut
      if (event.key === '?' || (event.key === '/' && event.shiftKey)) {
        event.preventDefault();
        setShowShortcuts(true);
        return;
      }

      // Don't process other shortcuts while action is pending
      if (isPending) return;

      // Match keyboard shortcuts
      const key = event.key.toLowerCase();
      const matchedShortcut = KEYBOARD_SHORTCUTS.find(
        (shortcut) =>
          shortcut.key === key && shortcut.enabledStatuses.includes(effectiveStatus)
      );

      if (matchedShortcut) {
        event.preventDefault();
        executeAction(matchedShortcut.action, handlers);
      }
    },
    [isOpen, effectiveStatus, isPending, showShortcuts, setShowShortcuts, closeDialog, handlers]
  );

  useEffect(() => {
    if (!isOpen) return;

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleKeyDown, isOpen]);
}

/**
 * Execute the appropriate action based on shortcut
 */
function executeAction(action: BookingAction, handlers: LifecycleActionHandlers): void {
  switch (action) {
    case 'check-in':
      void handlers.handleCheckIn();
      break;
    case 'check-out':
      void handlers.handleCheckOut();
      break;
    case 'no-show':
      void handlers.handleMarkNoShow();
      break;
    case 'undo-no-show':
      void handlers.handleUndoNoShow();
      break;
  }
}

